public class METJobDMUploadCustomerBusinessUnit extends RunBaseBatch //implements BatchRetryable
{
    NoYesId      isUpdateExistingData;
    DialogField  dlgIsUpdateExistingData;

    DialogRunbase dialog;

    private const str FileUploadName = 'FileUpload';
    private const str OkButtonName   = 'OkButton';

    FileUploadTemporaryStorageResult fileUploadResult;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        isUpdateExistingData
    #endmacro

}

Method.Source:
public Object dialog()
{
    dialog = super();

    DialogGroup       dialogGroup;
    FormBuildControl  formBuildControl;
    FileUploadBuild   dialogFileUpload;

    dialogGroup      = dialog.addGroup("File");
    formBuildControl = dialog.formBuildDesign().control(dialogGroup.name());

    dialogFileUpload = formBuildControl.addControlEx(classstr(FileUpload), FileUploadName);
    dialogFileUpload.style(FileUploadStyle::MinimalWithFilename);
    dialogFileUpload.baseFileUploadStrategyClassName(classstr(FileUploadTemporaryStorageStrategy));
    dialogFileUpload.fileTypesAccepted('.xlsx');
    dialogFileUpload.fileNameLabel("@SYS308842");

    dlgIsUpdateExistingData =
        dialog.addFieldValue(
            extendedtypestr(NoYesId),
            isUpdateExistingData,
            "Update existing data",
            "Override Business Unit if already populated");

    return dialog;
}

public void dialogPostRun(DialogRunbase _dialog)
{
    FileUpload fileUpload = this.getFormControl(_dialog, FileUploadName);
    fileUpload.notifyUploadCompleted += eventhandler(this.uploadCompleted);
    this.setDialogOkButtonEnabled(_dialog, false);
}

protected void uploadCompleted()
{
    FileUpload fileUpload = this.getFormControl(dialog, FileUploadName);
    fileUpload.notifyUploadCompleted -= eventhandler(this.uploadCompleted);
    this.setDialogOkButtonEnabled(dialog, true);
}

protected void setDialogOkButtonEnabled(DialogRunbase _dialog, boolean _isEnabled)
{
    FormControl okButtonControl = this.getFormControl(_dialog, OkButtonName);
    if (okButtonControl)
    {
        okButtonControl.enabled(_isEnabled);
    }
}

public boolean getFromDialog()
{
    FileUpload fileUploadControl = this.getFormControl(dialog, FileUploadName);
    fileUploadResult = fileUploadControl.getFileUploadResult();

    isUpdateExistingData = dlgIsUpdateExistingData.value();

    return super();
}

public void run()
{
    System.IO.MemoryStream memoryStreamFile;
    METFileReaderExcel    fileReader;
    CustTable             custTable;
    METBusinessUnit       mETBusinessUnit;
    int                   updatedCount = 0;
    int                   skippedCount = 0;

    try
    {
        if (!fileUploadResult)
        {
            throw error("No file uploaded.");
        }

        memoryStreamFile = fileUploadResult.openResult();

        fileReader = new METFileReaderExcel();
        fileReader.openFile(memoryStreamFile);
        fileReader.readHeaderRow();

        ttsbegin;

        while (fileReader.readNextRow())
        {
            AccountNum custAccount =
                fileReader.getStringByName("CUSTOMERACCOUNT");

            str businessUnit1 =
                fileReader.getStringByName("METBUSINESSNAME");
            str businessUnit2 =
                fileReader.getStringByName("METBUSINESSPREFIX");

            //str businessUnit;// = businessUnit1+any2Str(businessUnit2);

            if (!custAccount)
            {
                warning("Customer account is empty. Row skipped.");
                skippedCount++;
                continue;
            }
            /*select * from custTable join mETBusinessUnit
                where mETBusinessUnit.RecId == custTable.METBusinessUnitTableRefRecId
                    custTable.AccountNum == custAccount;*/

            select firstOnly forUpdate custTable
                where custTable.AccountNum == custAccount;

            if (!custTable)
            {
                warning(strFmt("Customer %1 not found.", custAccount));
                skippedCount++;
                continue;
            }

            // Skip if already populated and update flag = No
            if (!isUpdateExistingData && custTable.METBusinessUnitTableRefRecId)
            {
                skippedCount++;
                continue;
            }
            select * from mETBusinessUnit where mETBusinessUnit.BusinessName == businessUnit1
                        && mETBusinessUnit.StatePrefixStr == businessUnit2;
            //custTable.METBusinessUnitTableRefRecId = mETBusinessUnit.RecId;
             /*         
            //businessUnit = any2Str(mETBusinessUnit.RecId);
            // If Excel does not contain BU, auto-resolve
           /* if (!businessUnit)
            {
                /*select * from mETBusinessUnit where mETBusinessUnit.BusinessName == businessUnit1
                        && mETBusinessUnit.BusinessPrefix == businessUnit2;*/
               // businessUnit = 
                    //BusinessUnitHelper::resolve(custAccount);

                    businessUnit =  (mETBusinessUnit.BusinessName +any2Str( mETBusinessUnit.BusinessPrefix));
            }*/

            if (!businessUnit)
            {
                warning(strFmt(
                    "Business Unit could not be resolved for customer %1",
                    custAccount));
                skippedCount++;
                continue;
            }

            // Optional validation
            if (!businessUnit)//!BusinessUnitHelper::validate(businessUnit))
            {
                warning(strFmt(
                    "Invalid Business Unit %1 for customer %2",
                    businessUnit,
                    custAccount));
                skippedCount++;
                continue;
            }*/

            custTable.METBusinessUnitTableRefRecId =mETBusinessUnit.RecId;//any2Int64(businessUnit);
            custTable.update();

            updatedCount++;
        }

        ttscommit;

        info(strFmt("Update completed. Updated: %1, Skipped: %2",
            updatedCount, skippedCount));
    }
    catch (Exception::Error)
    {
        ttsabort;
        exceptionTextFallThrough();
    }
    finally
    {
        if (fileUploadResult)
        {
            fileUploadResult.deleteResult();
        }
        memoryStreamFile = null;
    }
}

public boolean unpack(container _packedClass)
{
    Version version = RunBase::getVersion(_packedClass);

    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList] = _packedClass;
            break;
        default:
            return false;
    }
    return true;
}

public NoYesId parmIsUpdateExistingData(
    NoYesId _isUpdateExistingData = isUpdateExistingData)
{
    isUpdateExistingData = _isUpdateExistingData;
    return isUpdateExistingData;
}

public static METJobDMUploadCustomerBusinessUnit construct()
{
    return new METJobDMUploadCustomerBusinessUnit();
}

static ClassDescription description()
{
    return "MET Job - Upload Customer Business Unit";
}

public static void main(Args _args)
{
    METJobDMUploadCustomerBusinessUnit job =
        METJobDMUploadCustomerBusinessUnit::construct();

    if (job.prompt())
    {
        job.runOperation();
    }
}
